76	// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
77	// depend on them.
78	func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
79		s.mu.Lock()
80		defer s.mu.Unlock()
81		old, ok := s.plans[id]
82		if !ok || old.OrgID != orgID {
83			return Plan{}, ErrNotFound
84		}
85		p := old
86		if err := f(&p); err != nil {
87			return Plan{}, err
88		}
89		p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
90		p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
91		p.Name = strings.TrimSpace(p.Name)
92		if err := checkPlan(p); err != nil {
93			return Plan{}, err
94		}
95		s.plans[id] = p
96		return p, nil
97	}
