244	// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
245	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
246		if !inv.Currency.Valid() {
247			return Invoice{}, invalid("unknown currency %q", inv.Currency)
248		}
249		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
250			return Invoice{}, invalid("the discount is 0 to 100 percent")
251		}
252		for _, l := range inv.Lines {
253			if l.Quantity <= 0 {
254				return Invoice{}, invalid("a line needs a positive quantity")
255			}
256		}
257		s.mu.Lock()
258		defer s.mu.Unlock()
259		org, ok := s.orgs[inv.OrgID]
260		if !ok {
261			return Invoice{}, ErrNotFound
262		}
263		c, ok := s.customers[inv.CustomerID]
264		if !ok {
265			return Invoice{}, ErrNotFound
266		}
267		if c.OrgID != inv.OrgID {
268			return Invoice{}, ErrCustomerOrgMismatch
269		}
270		inv.ID = s.newID("in")
271		inv.TaxRateBP = org.TaxRateBP
272		inv.Status = InvoiceOpen
273		inv.CreatedAt = now.UTC()
274		inv.PaidAt, inv.VoidedAt = nil, nil
275		inv = copyInvoice(inv)
276		s.invoices[inv.ID] = inv
277		return copyInvoice(inv), nil
278	}
