376	// ---- payments
377	
378	// CreatePayment records a payment attempt for one of the organization's invoices.
379	func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
380		s.mu.Lock()
381		defer s.mu.Unlock()
382		inv, ok := s.invoices[p.InvoiceID]
383		if !ok || inv.OrgID != p.OrgID {
384			return Payment{}, ErrNotFound
385		}
386		if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
387			return Payment{}, invalid("a payment succeeded or failed")
388		}
389		p.ID = s.newID("pay")
390		p.CreatedAt = now.UTC()
391		s.payments[p.ID] = p
392		return p, nil
393	}
394	
395	// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
396	func (s *Store) Payments(orgID, invoiceID string) []Payment {
397		s.mu.Lock()
398		defer s.mu.Unlock()
399		out := []Payment{}
400		for _, p := range s.payments {
401			if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
402				out = append(out, p)
403			}
404		}
405		sort.Slice(out, func(i, j int) bool {
406			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
407				return out[i].CreatedAt.Before(out[j].CreatedAt)
408			}
409			return out[i].ID < out[j].ID
410		})
411		return out
412	}
