299	// InvoiceFilter narrows ListInvoices.
300	type InvoiceFilter struct {
301		CustomerID     string
302		SubscriptionID string
303		Status         InvoiceStatus
304	}
305	
306	// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
307	func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
308		s.mu.Lock()
309		all := make([]Invoice, 0, len(s.invoices))
310		for _, inv := range s.invoices {
311			all = append(all, inv)
312		}
313		s.mu.Unlock()
314		out := []Invoice{}
315		for _, inv := range all {
316			c := cloneInvoice(inv)
317			if c.OrgID != orgID {
318				continue
319			}
320			if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
321				continue
322			}
323			out = append(out, c)
324		}
325		sort.Slice(out, func(i, j int) bool {
326			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
327				return out[i].CreatedAt.Before(out[j].CreatedAt)
328			}
329			return out[i].ID < out[j].ID
330		})
331		return out
332	}
333	
334	// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
335	func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
336		s.mu.Lock()
337		defer s.mu.Unlock()
338		old, ok := s.invoices[id]
339		if !ok || old.OrgID != orgID {
340			return Invoice{}, ErrNotFound
341		}
342		inv := copyInvoice(old)
343		if err := f(&inv); err != nil {
344			return Invoice{}, err
345		}
346		inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
347		s.invoices[id] = copyInvoice(inv)
348		return copyInvoice(inv), nil
349	}
350	
351	// copyInvoice is a deep copy, so callers cannot change stored lines.
352	func copyInvoice(inv Invoice) Invoice {
353		inv.Lines = append([]Line(nil), inv.Lines...)
354		for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
355			if *p != nil {
356				t := **p
357				*p = &t
358			}
359		}
360		return inv
361	}
362	
363	// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
364	func cloneInvoice(inv Invoice) Invoice {
365		b, err := json.Marshal(inv)
366		if err != nil {
367			return copyInvoice(inv)
368		}
369		var out Invoice
370		if err := json.Unmarshal(b, &out); err != nil {
371			return copyInvoice(inv)
372		}
373		return out
374	}
375	
376	// ---- payments
377	
378	// CreatePayment records a payment attempt for one of the organization's invoices.
379	func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
380		s.mu.Lock()
381		defer s.mu.Unlock()
382		inv, ok := s.invoices[p.InvoiceID]
383		if !ok || inv.OrgID != p.OrgID {
384			return Payment{}, ErrNotFound
385		}
386		if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
387			return Payment{}, invalid("a payment succeeded or failed")
388		}
389		p.ID = s.newID("pay")
390		p.CreatedAt = now.UTC()
391		s.payments[p.ID] = p
392		return p, nil
393	}
394	
395	// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
396	func (s *Store) Payments(orgID, invoiceID string) []Payment {
397		s.mu.Lock()
398		defer s.mu.Unlock()
399		out := []Payment{}
400		for _, p := range s.payments {
401			if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
402				out = append(out, p)
403			}
404		}
405		sort.Slice(out, func(i, j int) bool {
406			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
407				return out[i].CreatedAt.Before(out[j].CreatedAt)
408			}
409			return out[i].ID < out[j].ID
410		})
411		return out
412	}
