// checkTiers checks a metered plan's tiers: sorted by UpTo, strictly ascending, with a limit on every tier but the last.
func checkTiers(p Plan) error {
	switch {
	case p.UsageType != Metered:
		return badTiers("tiers need a metered plan")
	case p.TiersMode != Graduated && p.TiersMode != Volume:
		return badTiers("tiers_mode is graduated or volume")
	case len(p.Tiers) == 0:
		return badTiers("at least one tier")
	}
	var prev int64
	for i, t := range p.Tiers {
		last := i == len(p.Tiers)-1
		switch {
		case t.UnitAmount < 0 || t.FlatAmount < 0:
			return badTiers("amounts cannot be negative")
		case last && t.UpTo != nil:
			return badTiers("the last tier has no up_to")
		case !last && (t.UpTo == nil || *t.UpTo <= prev):
			return badTiers("up_to is a positive whole number, and rises from one tier to the next")
		}
		if t.UpTo != nil {
			prev = *t.UpTo
		}
	}
	return nil
}

func badTiers(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidTiers, fmt.Sprintf(format, args...))
}

