// tierIn is a tier as people write it: up_to is a whole number or null, and the amounts are in major units ("12.50").
type tierIn struct {
	UpTo       *json.Number `json:"up_to"`
	UnitAmount string       `json:"unit_amount"`
	FlatAmount string       `json:"flat_amount"`
}

// parseTiers reads tiers in major units into tiers in minor units. A missing flat_amount is 0.
func parseTiers(in []tierIn, c money.Currency) ([]store.Tier, error) {
	var tiers []store.Tier
	for _, t := range in {
		var tier store.Tier
		if t.UpTo != nil {
			n, err := strconv.ParseInt(t.UpTo.String(), 10, 64)
			if err != nil {
				return nil, fmt.Errorf("up_to is a whole number or null, not %s", t.UpTo)
			}
			tier.UpTo = &n
		}
		var err error
		if tier.UnitAmount, err = money.ParseMajor(t.UnitAmount, c); err != nil {
			return nil, err
		}
		if t.FlatAmount != "" {
			if tier.FlatAmount, err = money.ParseMajor(t.FlatAmount, c); err != nil {
				return nil, err
			}
		}
		tiers = append(tiers, tier)
	}
	return tiers, nil
}

