// them and needs no price.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TiersMode store.TiersMode `json:"tiers_mode"`
		Tiers     []tierIn        `json:"tiers"`
		TrialDays int             `json:"trial_days"`
	}
	if !decode(w, r, &in) {
		return
	}
	plan := store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, Interval: in.Interval, UsageType: in.UsageType,
		TiersMode: in.TiersMode, TrialDays: in.TrialDays}
	if len(in.Tiers) > 0 || in.TiersMode != "" {
		tiers, err := parseTiers(in.Tiers, in.Currency)
		if err != nil {
			writeError(w, http.StatusUnprocessableEntity, "invalid_tiers", err.Error())
			return
		}
		plan.Tiers = tiers
	} else {
		amount, err := money.ParseMajor(in.Price, in.Currency)
		if err != nil {
			if errors.Is(err, money.ErrInvalidAmount) {
				writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
				return
			}
			s.storeError(w, err)
			return
		}
		plan.UnitAmount = amount
	}
	pl, err := s.store.CreatePlan(plan, s.clock.Now())
	if err != nil {
		if errors.Is(err, store.ErrInvalidTiers) {
			writeError(w, http.StatusUnprocessableEntity, "invalid_tiers", err.Error())
			return
		}
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, viewPlan(pl))
